/**
 * @summary Full-text search across quotations and items by part number or supplier
 */
export const getSearchQuotationsUrl = (params: SearchQuotationsParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/search?${stringifiedParams}`
    : `/api/search`;
};

export const searchQuotations = async (
  params: SearchQuotationsParams,
  options?: RequestInit,
): Promise<SearchResults> => {
  return customFetch<SearchResults>(getSearchQuotationsUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getSearchQuotationsQueryKey = (
  params?: SearchQuotationsParams,
) => {
  return [`/api/search`, ...(params ? [params] : [])] as const;
};

